def test_readiness_distinguishes_planned_human_response_from_ordinary_production(
    tmp_path,
):
    text = human_source()
    prepared = asyncio.run(
        prepare_inputs(
            service=application(tmp_path, text),
            workspace_dir=str(tmp_path),
            process=process(text),
            source=text,
        )
    )
    dependencies = {item.binding_id: item for item in prepared.dependencies}
    assert dependencies["choice.choice_evidence"].classification == "upstream_produced"
    response = dependencies["second.second_input"]
    assert response.classification == "declared_human_response"
    assert response.interaction_step == "choice"
    assert response.producer_port == "choice_response"
    assert not prepared.reasons
    assert {binding.input_id for binding in prepared.snapshot.bindings} == {"brief"}

async def test_unknown_schema_or_graph_semantics_are_explicitly_unsupported(tmp_path):
    for text in (
        source(metadata={"version": 2, "value_schema": {"type": "string"}}),
        source(
            metadata={
                "version": 1,
                "value_schema": {"type": "string", "pattern": "unsafe"},
            }
        ),
        source(default="known").replace("when: null", 'when: "conditional"'),
    ):
        with pytest.raises(ProcessInterfaceError) as error:
            await prepare(tmp_path, text)
        assert error.value.reason.code == "READINESS_UNSUPPORTED"

def test_v3_restore_rejects_changed_or_unconsumed_subject(tmp_path, mutation):
    c = case(tmp_path)
    pending, answer, _ = respond(c)
    checkpoint = pending if mutation == "not_consumed" else consume(c, answer)
    state, record = copy.deepcopy(checkpoint.continuation), asdict(checkpoint)
    if mutation == "cursor":
        state["next_step_index"] = 2
    elif mutation == "completed":
        state["completed_step_ids"] = []
    elif mutation == "definition":
        c.plan = replace(c.plan, definition_digest="d" * 64)
    elif mutation == "input":
        c.values["brief"] = "Changed"
    elif mutation == "snapshot":
        frozen = InputSnapshot.create(
            **{**c.frozen.model_dump(exclude={"digest"}), "snapshot_id": "inputs-two"}
        )
        c.plan = replace(c.plan, input_snapshot=frozen)
    elif mutation == "schema":
        changed = copy.deepcopy(c.plan.steps[1].human_interaction)
        changed["response_schema"]["properties"]["selection"]["enum"] = ["b"]
        c.plan = replace(
            c.plan,
            steps=(
                c.plan.steps[0],
                replace(c.plan.steps[1], human_interaction=changed),
                *c.plan.steps[2:],
            ),
        )
    elif mutation == "upstream":
        state["responses"]["first.first_out"]["value"]["name"] = "Changed"
    elif mutation == "artifact":
        (tmp_path / "first.txt").write_text("Changed", encoding="utf-8")
    elif mutation == "response_ref":
        state["response_id"] = "other-response"
    elif mutation == "state_version":
        state["schema_version"] = 3.0
    with pytest.raises(WorkflowSourceExecutionError) as error:
        restore(c, checkpoint, state=state, checkpoint=record)
    assert error.value.code == "WORKFLOW_CONTINUATION_STALE"

